import argparse
import json
import subprocess
import sys
from pathlib import Path

from pyrpckit.codegen import PythonClientOptions, render_python_client, write_files

_REPO_ROOT = Path(__file__).resolve().parents[5]
_DEFAULT_OUTPUT = _REPO_ROOT / "generated" / "gateway_client" / "src" / "gateway_client"
_RUFF = str(Path(sys.executable).with_name("ruff.exe"))

_AUTHENTICATED_CLIENT = """# Generated by gateway-server from gateway.openrpc.json.
# Do not edit this file manually.

from websockets.asyncio.client import ClientConnection, connect

from gateway_client.client import GatewayClient
from gateway_client.transport import WebSocketTransport


async def connect_gateway(url: str, *, token: str) -> GatewayClient:
    async def open_socket(
        endpoint: str,
        *,
        subprotocols: list[str] | None,
    ) -> ClientConnection:
        return await connect(
            endpoint,
            subprotocols=subprotocols,
            additional_headers={"Authorization": f"Bearer {token}"},
        )

    transport = await WebSocketTransport.open(url, socket_factory=open_socket)
    return GatewayClient.from_transport(transport)
"""


def generate(schema_path: Path, output_directory: Path, *, check: bool = False) -> bool:
    """Generate the Gateway client with pyrpckit's bundled Python runtime."""
    document = json.loads(schema_path.read_text(encoding="utf-8"))
    options = PythonClientOptions(
        package="gateway_client",
        client_name="GatewayClient",
        source=schema_path.name,
        with_transport="websocket",
    )
    rendered = dict(render_python_client(document, options))
    rendered["authenticated.py"] = _AUTHENTICATED_CLIENT
    rendered["__init__.py"] = (
        rendered["__init__.py"]
        .replace("from gateway_client import endpoints", "from . import endpoints")
        .replace("from gateway_client.", "from .")
        .replace(
            "from .client import GatewayClient\n",
            "from .authenticated import connect_gateway\n"
            "from .client import GatewayClient\n",
        )
        .replace(
            '    "WebSocketTransport",\n',
            '    "WebSocketTransport",\n    "connect_gateway",\n',
        )
    )
    manifest = json.loads(rendered[".rpcgen/manifest.json"])
    manifest["files"].append("authenticated.py")
    manifest["files"].sort()
    rendered[".rpcgen/manifest.json"] = json.dumps(manifest, indent=2) + "\n"
    formatted = {
        path: _ruff_format(path, _separate_header(content))
        if path.endswith(".py")
        else content
        for path, content in rendered.items()
    }
    return bool(write_files(output_directory, formatted, check=check))


def _separate_header(content: str) -> str:
    lines = content.splitlines()
    if len(lines) >= 2 and lines[0].startswith("# Generated by "):
        while len(lines) > 2 and not lines[2]:
            lines.pop(2)
        lines.insert(2, "")
    return "\n".join(lines) + "\n"


def _ruff_format(filename: str, content: str) -> str:
    sorted_content = subprocess.run(
        [_RUFF, "check", "--fix-only", "--stdin-filename", filename, "-"],
        cwd=_REPO_ROOT,
        input=content,
        capture_output=True,
        text=True,
        check=True,
    ).stdout
    return subprocess.run(
        [_RUFF, "format", "--stdin-filename", filename, "-"],
        cwd=_REPO_ROOT,
        input=sorted_content,
        capture_output=True,
        text=True,
        check=True,
    ).stdout


def main() -> None:
    parser = argparse.ArgumentParser(description="Generate the typed Gateway client")
    parser.add_argument("schema", type=Path)
    parser.add_argument("--output", type=Path, default=_DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true")
    arguments = parser.parse_args()
    changed = generate(arguments.schema, arguments.output, check=arguments.check)
    if arguments.check and changed:
        parser.error("generated client is out of date")


if __name__ == "__main__":
    main()
